/*
 * -tts: speaks the reply of a command. The command's own `tts: true` in the definition turns it on, and
 * it is only a shortcut for /tts with the command inside braces:
 *   /crypto -tts BTC ETH   →   /tts -q {/crypto -q BTC ETH}
 * (the -q goes in when the command has it; without it the full reply is spoken, cleaned by /tts).
 * Only the default /tts: voice, speed and engine come from the tts.* settings. The /tts goes with -q: just the
 * voice note, with no "generating..." and no footer ("Audio generated below", "Generated by Piper").
 */

const TTS_OPTION = /(^|\s)-tts(?=\s|$)/;

/**
 * "/tts -q {/crypto -q BTC}" for a command with `tts: true` that received -tts, or null.
 * @param {{ cmd: string, tts?: boolean, cmd_opts?: object[] }} command
 * @param {string} args  what came after the command
 */
function ttsRewrite(command, args) {
    if (!command?.tts || !TTS_OPTION.test(args)) return null;

    const rest = args.replace(TTS_OPTION, '$1').replace(/\s+/g, ' ').trim();
    const hasQuiet = (command.cmd_opts ?? []).some(o => o.opts?.includes('quiet'));
    const quiet = hasQuiet && !/(^|\s)-(q|quiet)(?=\s|$)/.test(rest) ? ' -q' : '';

    return `/tts -q {${command.cmd}${quiet}${rest ? ` ${rest}` : ''}}`;
}

module.exports = { ttsRewrite };
